//! `moagan coverage` inspection helpers. ADR-0002.
//!
//! Read the `*.profraw` files emitted by the runtime coverage
//! recorder and produce a human-readable summary. The full HTML
//! report is generated by shelling out to `grcov` (or the
//! `llvm-profdata` + `llvm-cov` fallback); the text view this
//! module produces works without any external tool and is what the
//! `moagan coverage` CLI shows in the terminal.

use std::path::{Path, PathBuf};

use crate::error::{Error, Result};
use crate::fs_layout::RunDir;
use crate::ids::RunId;

/// Result of a coverage inspection. Built without depending on
/// `grcov` or `llvm-cov` so the text view always works.
#[derive(Debug, Clone)]
pub struct CoverageReport {
    /// Run id the report is for.
    pub run_id: RunId,
    /// Directory the `profraw` files live in.
    pub coverage_dir: PathBuf,
    /// `*.profraw` files found, sorted by name (which is
    /// `seq`-suffixed, so the order matches the temporal order of
    /// the snapshots).
    pub profraws: Vec<ProfrawEntry>,
    /// `true` when the directory exists and contains at least one
    /// `profraw` file. `false` means the run was not instrumented
    /// (default build, or the `coverage` feature off, or no
    /// snapshots were taken).
    pub instrumented: bool,
}

/// One `*.profraw` file in the coverage directory.
#[derive(Debug, Clone)]
pub struct ProfrawEntry {
    /// Absolute path to the file.
    pub path: PathBuf,
    /// File name only (for table-style output).
    pub name: String,
    /// Size in bytes.
    pub size_bytes: u64,
}

/// Scan `<run_dir>/telemetry/coverage/` and return every
/// `*.profraw` file along with its size. Missing directory or
/// empty directory is **not** an error: the report is just marked
/// `instrumented = false` so the CLI can print a clear "no
/// coverage data" hint instead of a stack trace.
pub fn scan_run(run_dir: &RunDir<'_>) -> Result<CoverageReport> {
    let coverage_dir = run_dir.coverage();
    if !coverage_dir.is_dir() {
        return Ok(CoverageReport {
            run_id: run_dir_id(run_dir),
            coverage_dir,
            profraws: Vec::new(),
            instrumented: false,
        });
    }
    let mut profraws: Vec<ProfrawEntry> = Vec::new();
    for entry in std::fs::read_dir(&coverage_dir)? {
        let entry = entry?;
        let path = entry.path();
        if path.extension().and_then(|e| e.to_str()) != Some("profraw") {
            continue;
        }
        let meta = entry.metadata()?;
        let name = path
            .file_name()
            .map(|n| n.to_string_lossy().into_owned())
            .unwrap_or_default();
        profraws.push(ProfrawEntry {
            path,
            name,
            size_bytes: meta.len(),
        });
    }
    profraws.sort_by(|a, b| a.name.cmp(&b.name));
    let instrumented = !profraws.is_empty();
    Ok(CoverageReport {
        run_id: run_dir_id(run_dir),
        coverage_dir,
        profraws,
        instrumented,
    })
}

/// Render the report as a `moagan coverage`-style text table. The
/// output is deterministic so it can be pinned in golden tests.
pub fn render_text(report: &CoverageReport) -> String {
    use std::fmt::Write;
    let mut out = String::new();
    let _ = writeln!(out, "run {}  coverage report", report.run_id.short());
    let _ = writeln!(out, "  dir : {}", report.coverage_dir.display());
    if !report.instrumented {
        let _ = writeln!(
            out,
            "  status: not instrumented — no `*.profraw` files in the coverage directory"
        );
        let _ = writeln!(
            out,
            "  hint  : rebuild with `--features coverage` and \
             `RUSTFLAGS=\"-Cinstrument-coverage\"` to enable \
             SanCov runtime coverage"
        );
        return out;
    }
    let _ = writeln!(
        out,
        "  status: instrumented — {} `profraw` file(s)",
        report.profraws.len()
    );
    let _ = writeln!(out);
    let _ = writeln!(out, "  {:<60}  {:>10}", "file", "size (B)");
    let _ = writeln!(out, "  {}  {}", "-".repeat(60), "-".repeat(10));
    for entry in &report.profraws {
        let _ = writeln!(out, "  {:<60}  {:>10}", entry.name, entry.size_bytes);
    }
    let _ = writeln!(out);
    let _ = writeln!(
        out,
        "  to render the per-line coverage report, run from a shell:"
    );
    let _ = writeln!(
        out,
        "    grcov {} --binary-path <path-to-coverage-binary> \\",
        report.coverage_dir.display()
    );
    let _ = writeln!(
        out,
        "         -s <path-to-source-tree> -t html --branch --ignore-not-existing \\"
    );
    let _ = writeln!(out, "         -o coverage-<run_id>.html");
    let _ = writeln!(out);
    let _ = writeln!(out, "  if `grcov` is not on PATH, the manual fallback is:");
    let _ = writeln!(
        out,
        "    llvm-profdata merge -sparse {}/*.profraw -o merged.profdata",
        report.coverage_dir.display()
    );
    let _ = writeln!(
        out,
        "    llvm-cov show <coverage-binary> --instr-profile merged.profdata"
    );
    out
}

/// Look up the run id embedded in a `RunDir` (the trailing
/// component of the root path). Used to label the report.
fn run_dir_id(run_dir: &RunDir<'_>) -> RunId {
    run_dir
        .root()
        .file_name()
        .and_then(|n| n.to_str())
        .and_then(|s| s.parse().ok())
        .unwrap_or_default()
}

/// Detect whether `grcov` is on `PATH`. Best-effort: the check
/// itself is cheap and never fails the inspection.
pub fn grcov_available() -> bool {
    which("grcov").is_some()
}

fn which(cmd: &str) -> Option<PathBuf> {
    let path = std::env::var_os("PATH")?;
    for dir in std::env::split_paths(&path) {
        let candidate = dir.join(cmd);
        if candidate.is_file() {
            return Some(candidate);
        }
    }
    None
}

/// Filter the report down to the `profraw` files whose name
/// contains `tag` (case-insensitive substring match). Used by
/// `moagan coverage <run_id> --since-error <code>` to narrow the
/// output to the window around a specific event.
pub fn filter_by_tag(report: &CoverageReport, tag: &str) -> CoverageReport {
    let needle = tag.to_lowercase();
    let profraws = report
        .profraws
        .iter()
        .filter(|e| e.name.to_lowercase().contains(&needle))
        .cloned()
        .collect();
    CoverageReport {
        run_id: report.run_id,
        coverage_dir: report.coverage_dir.clone(),
        profraws,
        instrumented: !report.profraws.is_empty() && report.instrumented,
    }
}

/// Verify the report has data; return a clean `InvalidState` error
/// otherwise. The CLI uses this to map an empty report to a
/// non-zero exit code with a friendly message.
pub fn ensure_instrumented(report: &CoverageReport) -> Result<()> {
    if !report.instrumented {
        return Err(Error::InvalidState(format!(
            "run {} has no runtime coverage data; rebuild with \
             `RUSTFLAGS=\"-Cinstrument-coverage\" cargo build --features coverage` \
             to enable it",
            report.run_id.short()
        )));
    }
    Ok(())
}

/// Return the absolute path to the `profraw` file for a given
/// snapshot tag, if any. Used by the (planned) HTML render path
/// to pick a specific snapshot.
pub fn find_profraw<'a>(report: &'a CoverageReport, tag: &str) -> Option<&'a ProfrawEntry> {
    report.profraws.iter().find(|e| e.name.contains(tag))
}

/// Path the report is rooted at. Convenience for the CLI.
pub fn coverage_dir(report: &CoverageReport) -> &Path {
    &report.coverage_dir
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::test_support::with_moagan_home;

    #[test]
    fn scan_empty_run_marks_not_instrumented() {
        with_moagan_home("coverage_scan_empty", |home_path| {
            let home = crate::fs_layout::MoaganHome::at(home_path.to_path_buf());
            let run_dir = home.run_dir(RunId::new());
            run_dir.ensure().unwrap();
            let report = scan_run(&run_dir).unwrap();
            assert!(!report.instrumented);
            assert_eq!(report.profraws.len(), 0);
        });
    }

    #[test]
    fn scan_finds_profraw_files() {
        with_moagan_home("coverage_scan_finds", |home_path| {
            let home = crate::fs_layout::MoaganHome::at(home_path.to_path_buf());
            let run_dir = home.run_dir(RunId::new());
            run_dir.ensure().unwrap();
            // Drop two fake `profraw` files into the coverage dir.
            std::fs::write(run_dir.coverage().join("run-1.profraw"), b"a").unwrap();
            std::fs::write(run_dir.coverage().join("run-1-phase-1-0.profraw"), b"bb").unwrap();
            std::fs::write(
                run_dir.coverage().join("run-1-call-call-1-1.profraw"),
                b"ccc",
            )
            .unwrap();
            // A non-`profraw` neighbour is ignored.
            std::fs::write(run_dir.coverage().join("README"), b"x").unwrap();

            let report = scan_run(&run_dir).unwrap();
            assert!(report.instrumented);
            assert_eq!(report.profraws.len(), 3);
            // Sorted by name, so the snapshot files come first.
            assert!(report.profraws[0].name.contains("call-"));
            assert!(report.profraws[1].name.contains("phase-"));
            assert!(report.profraws[2].name.starts_with("run-1.profraw"));
            // Sizes are recorded.
            assert_eq!(report.profraws[0].size_bytes, 3);
            assert_eq!(report.profraws[1].size_bytes, 2);
            assert_eq!(report.profraws[2].size_bytes, 1);
        });
    }

    #[test]
    fn render_text_mentions_grcov_fallback() {
        with_moagan_home("coverage_render_text", |home_path| {
            let home = crate::fs_layout::MoaganHome::at(home_path.to_path_buf());
            let run_dir = home.run_dir(RunId::new());
            run_dir.ensure().unwrap();
            std::fs::write(run_dir.coverage().join("run.profraw"), b"x").unwrap();
            let report = scan_run(&run_dir).unwrap();
            let text = render_text(&report);
            assert!(text.contains("grcov"));
            assert!(text.contains("llvm-profdata"));
        });
    }

    #[test]
    fn render_text_explains_when_not_instrumented() {
        with_moagan_home("coverage_render_not_inst", |home_path| {
            let home = crate::fs_layout::MoaganHome::at(home_path.to_path_buf());
            let run_dir = home.run_dir(RunId::new());
            run_dir.ensure().unwrap();
            let report = scan_run(&run_dir).unwrap();
            let text = render_text(&report);
            assert!(text.contains("not instrumented"));
            assert!(text.contains("RUSTFLAGS"));
        });
    }

    #[test]
    fn filter_by_tag_narrows_results() {
        with_moagan_home("coverage_filter_tag", |home_path| {
            let home = crate::fs_layout::MoaganHome::at(home_path.to_path_buf());
            let run_dir = home.run_dir(RunId::new());
            run_dir.ensure().unwrap();
            std::fs::write(run_dir.coverage().join("run-phase-1-0.profraw"), b"a").unwrap();
            std::fs::write(run_dir.coverage().join("run-call-c1-1.profraw"), b"b").unwrap();
            let report = scan_run(&run_dir).unwrap();
            let filtered = filter_by_tag(&report, "phase");
            assert_eq!(filtered.profraws.len(), 1);
            assert!(filtered.profraws[0].name.contains("phase"));
        });
    }

    #[test]
    fn ensure_instrumented_errors_on_empty_report() {
        with_moagan_home("coverage_ensure_empty", |home_path| {
            let home = crate::fs_layout::MoaganHome::at(home_path.to_path_buf());
            let run_dir = home.run_dir(RunId::new());
            run_dir.ensure().unwrap();
            let report = scan_run(&run_dir).unwrap();
            let err = ensure_instrumented(&report).unwrap_err();
            assert!(
                matches!(err, Error::InvalidState(_)),
                "expected InvalidState, got {err:?}"
            );
        });
    }
}
